// We wrap everything in `verus! { ... }` so that Verus picks up
// both the spec‐level and proof obligations.
verus! {
    // A small helper to compute max(a,b,c) at specification level
    spec fn max3(a: i8, b: i8, c: i8) -> i8
        ensures |r: i8| r == a.max(b).max(c)
    {
        if a > b {
            if a > c { a } else { c }
        } else {
            if b > c { b } else { c }
        }
    }

    #[verus::verus]
    fn solve(a: i8, b: i8, c: i8) -> i8
        // input bounds
        requires  0 <= a && a <= 50
               && 0 <= b && b <= 50
               && 0 <= c && c <= 50
        // post‐condition characterizes the unique minimal r
        ensures(|r: i8| {
            // Lift to mathematical `int` to avoid overflow in specs
            let sum: int = a as int + b as int + c as int;
            let m0: int = max3(a, b, c) as int;
            let r_i: int = r as int;

            // 1) non‐negative result
            0 <= r_i

            // 2) after r operations the total sum is exactly 3·T
            //    for some T ≥ m0
            && (sum + 2 * r_i) % 3 == 0
            && (sum + 2 * r_i) / 3 >= m0

            // 3) minimality: any k satisfying the same reachability
            //    constraints must be ≥ r_i
            && forall(|k: int| 
                  0 <= k
                  && (sum + 2 * k) % 3 == 0
                  && (sum + 2 * k) / 3 >= m0
                  ==> r_i <= k)
        })
    {
        // Compute sum and the maximum of a,b,c
        let sum = (a as int) + (b as int) + (c as int);
        let m0  = max3(a, b, c) as int;

        // We choose the smallest target T ≥ m0 whose parity
        // matches sum (so that 3·T − sum is even).
        let T = if (m0 % 2) == (sum % 2) { m0 } else { m0 + 1 };

        // Total “deficit” to make (a+b+c) go up to 3·T:
        let diff = 3 * T - sum;
        // must be even by construction
        assert(diff % 2 == 0);
        // each operation adds exactly 2 to the sum
        let ops = diff / 2;
        assert(0 <= ops);

        // Fit back into an i8 (we know it is small)
        ops as i8
    }
}